/* ===== GRAMMAR EXTRA: 10 additional original exercises per existing topic =====
   Shape: see content/CONTENT_SPEC.md section 4. Distractors target typical errors of Portuguese-speaking learners. */
export const GRAMMAR_EXTRA = {
"tenses":[
 {lvl:1,cefr:"B1",q:"Last summer, I ___ my grandparents in the countryside for two weeks.",opts:["visit","have visited","visited"],a:2,why:"'Last summer' is a finished period in the past, so the past simple 'visited' is correct. 'Have visited' is wrong because the present perfect cannot be combined with a finished time expression.",natural:"Last summer, I spent two weeks visiting my grandparents in the countryside."},
 {lvl:1,cefr:"B1",q:"Every year, thousands of tourists ___ the historic centre of the city.",opts:["visit","are visiting","visited"],a:0,why:"'Every year' signals a regular, repeated situation, so the present simple 'visit' is needed. 'Are visiting' describes a temporary action happening now, not a yearly pattern.",natural:"Every year, the historic city centre attracts thousands of tourists."},
 {lvl:2,cefr:"B2",q:"The graph shows that coffee consumption ___ steadily between 1990 and 2005.",opts:["has risen","rose","rises"],a:1,why:"The period 1990-2005 is completely finished, so Task 1 requires the past simple 'rose'. 'Has risen' is wrong because the present perfect links to now, and the data ends in 2005.",natural:"Coffee consumption rose steadily between 1990 and 2005."},
 {lvl:2,cefr:"B2",q:"At the moment, my city ___ a new metro line, so traffic is terrible.",opts:["builds","is building","has built"],a:1,why:"'At the moment' describes a temporary action in progress, so the present continuous 'is building' fits. 'Builds' (present simple) describes habits or permanent facts, and 'has built' would mean the work is finished.",natural:"My city is building a new metro line at the moment, so the traffic is terrible."},
 {lvl:2,cefr:"B2",q:"I usually ___ to the gym three times a week, but this month I'm too busy.",opts:["go","am going","went"],a:0,why:"'Usually' and 'three times a week' describe a routine, which takes the present simple 'go'. 'Am going' would suggest a temporary arrangement, which contradicts 'usually'.",natural:"I normally go to the gym three times a week, but I've been too busy this month."},
 {lvl:2,cefr:"B2",q:"When the pandemic started, many companies ___ their staff to work from home.",opts:["were allowing","allowed","have allowed"],a:1,why:"A single completed action at a specific past moment ('when the pandemic started') takes the past simple 'allowed'. 'Were allowing' would describe a background action already in progress, and 'have allowed' cannot be used with a finished past time.",natural:"When the pandemic began, many companies allowed their employees to work remotely."},
 {lvl:2,cefr:"B2",q:"Experts predict that average global temperatures ___ by at least 1.5°C before the end of the century.",opts:["will rise","rise","are rising"],a:0,why:"A prediction about the future after 'predict that' needs 'will rise'. 'Rise' in the present simple states a general fact, not a forecast, which is a common transfer from Portuguese 'prevêem que as temperaturas sobem'.",natural:"Experts predict that global temperatures will rise by at least 1.5°C before the end of the century."},
 {lvl:3,cefr:"C1",q:"By the end of the period, the figure for Japan ___ that of Germany.",opts:["had overtaken","overtook","has overtaken"],a:0,why:"'By the end of the period' (a past point) shows an action completed before that point, so the past perfect 'had overtaken' is most accurate. 'Has overtaken' is wrong because the period is finished; 'overtook' does not express completion before the reference point.",natural:"By the end of the period, Japan's figure had overtaken Germany's."},
 {lvl:3,cefr:"C1",q:"According to its expansion plan, the company ___ more than 500 new stores by 2030.",opts:["will have opened","will open","opens"],a:0,why:"'By 2030' looks back from a future point at a completed total, so the future perfect 'will have opened' is required. 'Will open' focuses on the action itself and sounds odd with 'by + date' and a cumulative number.",natural:"The company plans to have opened more than 500 new stores by 2030."},
 {lvl:3,cefr:"C1",q:"Sales ___ for three consecutive years before they finally recovered in 2018.",opts:["have been falling","had been falling","were fallen"],a:1,why:"A continuous trend that lasted up to another past event ('recovered in 2018') takes the past perfect continuous 'had been falling'. 'Have been falling' connects to the present, which contradicts the 2018 recovery; 'were fallen' is not a valid form because 'fall' is intransitive.",natural:"Sales had been declining for three consecutive years before finally recovering in 2018."}
],
"present-perfect":[
 {lvl:1,cefr:"B1",q:"We have known each other ___ ten years.",opts:["since","for","during"],a:1,why:"'For' is used with a length of time (ten years). 'Since' needs a starting point (since 2015), so 'since ten years' is a typical error from Portuguese 'há dez anos/desde'.",natural:"We have known each other for ten years."},
 {lvl:1,cefr:"B1",q:"___ you ever ___ to another country?",opts:["Did / go","Have / been","Have / went"],a:1,why:"Questions about life experience with 'ever' use the present perfect: 'Have you ever been...?'. 'Have... went' is wrong because the present perfect needs the past participle (been/gone), not the past simple.",natural:"Have you ever been abroad?"},
 {lvl:2,cefr:"B2",q:"Since the new law was introduced, the number of road accidents ___ significantly.",opts:["has dropped","dropped","drops"],a:0,why:"'Since + past event' describes a period continuing up to now, so the main clause needs the present perfect 'has dropped'. 'Dropped' in the past simple does not connect the change to the present.",natural:"Since the new law was introduced, road accidents have fallen significantly."},
 {lvl:2,cefr:"B2",q:"I ___ three essays so far this month, and I'm hoping to finish a fourth.",opts:["wrote","have written","have been writing"],a:1,why:"'So far this month' is an unfinished period and the focus is on a completed number (three), so 'have written' is correct. 'Have been writing' stresses ongoing activity and is not used with a precise quantity of finished items.",natural:"I've written three essays so far this month and hope to finish a fourth."},
 {lvl:2,cefr:"B2",q:"Over the past few years, house prices in big cities ___ beyond the reach of many young people.",opts:["rose","have risen","are rising"],a:1,why:"'Over the past few years' is a period that continues to the present, so the present perfect 'have risen' is required. The past simple 'rose' needs a finished time, and 'are rising' loses the idea of a result up to now.",natural:"Over the past few years, house prices in major cities have risen beyond the reach of many young people."},
 {lvl:2,cefr:"B2",q:"I'm exhausted because I ___ for my exam all morning.",opts:["studied","have been studying","study"],a:1,why:"An activity that has continued until now and explains a present result (being exhausted) takes the present perfect continuous 'have been studying'. 'Studied' presents it as finished and disconnected from now.",natural:"I'm exhausted because I've been studying for my exam all morning."},
 {lvl:2,cefr:"B2",q:"The government ___ yet decided how to fund the new hospital.",opts:["didn't","hasn't","doesn't"],a:1,why:"'Yet' in negative sentences goes with the present perfect: 'hasn't yet decided'. 'Didn't yet decide' is a common transfer from Portuguese 'ainda não decidiu', but English uses the present perfect here.",natural:"The government has not yet decided how to fund the new hospital."},
 {lvl:3,cefr:"C1",q:"Scientists ___ the effects of microplastics for over a decade, yet many questions remain unanswered.",opts:["have been investigating","are investigating","investigated"],a:0,why:"'For over a decade' with research that is still ongoing requires the present perfect continuous 'have been investigating'. 'Are investigating for over a decade' is a Portuguese-style error ('estão investigando há mais de uma década').",natural:"Scientists have been investigating the effects of microplastics for over a decade, yet many questions remain unanswered."},
 {lvl:3,cefr:"C1",q:"It is the most innovative proposal that the committee ___ in years.",opts:["has received","received","receives"],a:0,why:"A superlative followed by an experience up to now ('in years') takes the present perfect 'has received'. 'Received' would require a finished time frame, which 'in years' does not give.",natural:"It is the most innovative proposal the committee has received in years."},
 {lvl:3,cefr:"C1",q:"Since I ___ working on cruise ships, my English ___ enormously.",opts:["started / has improved","have started / improved","started / improved"],a:0,why:"After 'since', the starting event is in the past simple ('started'), while the main clause describing change up to now takes the present perfect ('has improved'). Reversing the tenses, or using the past simple in both, breaks the link with the present.",natural:"Since I started working on cruise ships, my English has improved enormously."}
],
"articles":[
 {lvl:1,cefr:"A2",q:"My sister is ___ engineer at a large company.",opts:["(no article)","an","the"],a:1,why:"Jobs after 'be' need 'a/an' in English, and 'engineer' begins with a vowel sound, so 'an' is correct. Leaving out the article copies Portuguese 'ela é engenheira'.",natural:"My sister is an engineer at a large company."},
 {lvl:1,cefr:"B1",q:"I usually go to work by ___ bus.",opts:["the","a","(no article)"],a:2,why:"'By + means of transport' takes no article: by bus, by car, by train. 'By the bus' is incorrect because the phrase refers to the method, not a specific bus.",natural:"I usually take the bus to work."},
 {lvl:2,cefr:"B2",q:"___ crime rate in urban areas fell by 12% over the decade.",opts:["The","A","(no article)"],a:0,why:"'Rate' is a singular countable noun made specific by 'in urban areas', so it needs 'the'. Omitting the article leaves a singular countable noun without a determiner, which is never correct.",natural:"The urban crime rate fell by 12% over the decade."},
 {lvl:2,cefr:"B2",q:"In many countries, ___ elderly are living longer than ever before.",opts:["(no article)","the","an"],a:1,why:"'The + adjective' refers to a whole group of people (the elderly, the poor, the young). Without 'the', 'elderly' is just an adjective and cannot act as a subject.",natural:"In many countries, older people are living longer than ever before."},
 {lvl:2,cefr:"B2",q:"___ life in big cities can be stressful and expensive.",opts:["The","(no article)","A"],a:1,why:"'Life' used in a general sense is uncountable and takes no article. 'The life in big cities' is a direct translation of Portuguese 'a vida nas grandes cidades'.",natural:"Life in big cities can be stressful and expensive."},
 {lvl:2,cefr:"B2",q:"The chart compares ___ amount of water used in four countries.",opts:["an","the","(no article)"],a:1,why:"'Amount' is made specific by 'of water used in four countries', so 'the amount' is needed. 'An amount' would mean an unspecified quantity, which does not fit a chart description.",natural:"The chart compares water consumption in four countries."},
 {lvl:2,cefr:"B2",q:"In 2020, ___ United States produced more electricity from gas than from coal.",opts:["The","(no article)","A"],a:0,why:"Country names containing a plural or a word like 'States', 'Kingdom' or 'Republic' take 'the': the United States, the UK. Most single-word country names (Brazil, Japan) take no article.",natural:"In 2020, the United States generated more electricity from gas than from coal."},
 {lvl:3,cefr:"C1",q:"___ access to clean water is a basic human right, yet ___ access that rural communities have is often limited.",opts:["(no article) / the","The / the","(no article) / (no article)"],a:0,why:"The first 'access' is a general, uncountable idea, so no article. The second is defined by the relative clause 'that rural communities have', so it needs 'the'. Using 'the' in both places is the typical Portuguese pattern.",natural:"Access to clean water is a basic human right, yet the access rural communities have is often limited."},
 {lvl:3,cefr:"C1",q:"The internet has had ___ profound impact on the way ___ young people socialise.",opts:["a / (no article)","the / the","(no article) / the"],a:0,why:"'Impact' is countable and singular here, so it needs 'a' ('have a profound impact on'). 'Young people' is a general plural group, so no article. 'The young people' would refer to a specific group already mentioned.",natural:"The internet has had a profound impact on how young people socialise."},
 {lvl:3,cefr:"C1",q:"Compared with ___ 1990s, ___ unemployment was considerably lower in the following decade.",opts:["the / (no article)","(no article) / the","the / the"],a:0,why:"Decades always take 'the' (the 1990s). 'Unemployment' as a general economic concept is uncountable and takes no article. 'The unemployment' is a frequent Portuguese transfer ('o desemprego').",natural:"Unemployment was considerably lower in the 2000s than in the 1990s."}
],
"prepositions":[
 {lvl:1,cefr:"A2",q:"The museum is closed ___ Mondays.",opts:["in","on","at"],a:1,why:"Days of the week take 'on' (on Monday, on Mondays). 'In' is for months, years and seasons, and 'at' is for clock times.",natural:"The museum is closed on Mondays."},
 {lvl:1,cefr:"B1",q:"I'm not very good ___ cooking, but I'm learning.",opts:["in","at","on"],a:1,why:"The fixed adjective + preposition combination is 'good at' (+ noun or -ing). 'Good in' is a direct translation of Portuguese 'bom em'.",natural:"I'm not a great cook, but I'm learning."},
 {lvl:2,cefr:"B2",q:"The proportion of women in parliament reached a peak ___ 35% in 2018.",opts:["of","in","with"],a:0,why:"'A peak of + figure' gives the highest value. 'A peak in' is used with a time ('a peak in 2018'), not with the figure itself.",natural:"The proportion of women in parliament peaked at 35% in 2018."},
 {lvl:2,cefr:"B2",q:"Many students worry ___ finding a job after graduation.",opts:["with","about","for"],a:1,why:"The verb is 'worry about'. 'Worry with' is a transfer from Portuguese 'preocupar-se com'.",natural:"Many students are anxious about finding a job after graduation."},
 {lvl:2,cefr:"B2",q:"The decision to close the factory resulted ___ hundreds of job losses.",opts:["in","from","on"],a:0,why:"'Result in' introduces the consequence (job losses). 'Result from' introduces the cause, so it would reverse the logic of the sentence.",natural:"The factory closure resulted in hundreds of job losses."},
 {lvl:2,cefr:"B2",q:"Exports of coffee remained stable ___ around 2 million tonnes throughout the decade.",opts:["in","at","on"],a:1,why:"In Task 1, a level where a figure stays or ends is introduced by 'at' (remained stable at, peaked at, levelled off at). 'In' is not used before a figure in this pattern.",natural:"Coffee exports remained stable at around 2 million tonnes throughout the decade."},
 {lvl:2,cefr:"B2",q:"In my opinion, the government should spend more money ___ public health.",opts:["in","with","on"],a:2,why:"The pattern is 'spend money on something'. 'Spend with' and 'spend in' come from Portuguese 'gastar com/em'; 'invest in' would take 'in', but 'spend' does not.",natural:"In my view, the government should spend more on public health."},
 {lvl:3,cefr:"C1",q:"There was a marked difference ___ the two age groups ___ their use of social media.",opts:["between / in","among / of","of / on"],a:0,why:"'A difference between' is used with two groups, and 'a difference in' introduces the area being compared. 'Among' is for three or more, and 'difference of' is used for a quantity (a difference of 10%).",natural:"The two age groups differed markedly in their use of social media."},
 {lvl:3,cefr:"C1",q:"The rise in obesity has been attributed ___ sedentary lifestyles and poor diet.",opts:["to","for","of"],a:0,why:"'Attribute something to a cause' is fixed. 'Attributed for' is a common error, possibly influenced by 'responsible for'.",natural:"The rise in obesity has been attributed to sedentary lifestyles and poor diet."},
 {lvl:3,cefr:"C1",q:"The policy had little effect ___ consumer behaviour, contrary ___ expectations.",opts:["on / to","in / of","over / with"],a:0,why:"The collocations are 'an effect on' and 'contrary to'. 'Effect in' and 'contrary of' are not used in standard English.",natural:"Contrary to expectations, the policy had little effect on consumer behaviour."}
],
"conditionals":[
 {lvl:1,cefr:"B1",q:"If you heat ice, it ___.",opts:["melts","melted","would melt"],a:0,why:"Scientific facts that are always true use the zero conditional: present simple in both clauses. 'Would melt' suggests an imaginary situation, which does not fit a fact.",natural:"If you heat ice, it melts."},
 {lvl:1,cefr:"B1",q:"If I ___ the job, I will move to London.",opts:["get","will get","got"],a:0,why:"In the first conditional, the if-clause uses the present simple even for the future. 'If I will get' is a transfer from the Portuguese future subjunctive 'se eu conseguir'.",natural:"If I get the job, I'll move to London."},
 {lvl:2,cefr:"B2",q:"If cities ___ more cycle lanes, fewer people would drive to work.",opts:["built","build","will build"],a:0,why:"'Would drive' in the main clause shows a hypothetical (second) conditional, which needs the past simple 'built' in the if-clause. 'Build' would require 'will' in the main clause.",natural:"If cities built more cycle lanes, fewer people would drive to work."},
 {lvl:2,cefr:"B2",q:"Unless the government ___ action now, the problem will get worse.",opts:["takes","doesn't take","will take"],a:0,why:"'Unless' already means 'if not', so it takes a positive verb: 'unless the government takes'. 'Unless... doesn't take' creates a double negative, and 'will' is not used after 'unless'.",natural:"Unless the government acts now, the problem will get worse."},
 {lvl:2,cefr:"B2",q:"If I were you, I ___ apply for the scholarship.",opts:["will","would","should to"],a:1,why:"'If I were you' is a hypothetical form for advice and needs 'would' in the main clause. 'Will' does not match the unreal condition, and 'should to' is never correct because modals are followed by the bare infinitive.",natural:"If I were you, I'd apply for the scholarship."},
 {lvl:2,cefr:"B2",q:"If I had known about the traffic, I ___ earlier.",opts:["would leave","would have left","had left"],a:1,why:"An unreal past situation (third conditional) needs 'would have + past participle' in the main clause. 'Would leave' refers to the present or future, so it does not match 'had known'.",natural:"If I'd known about the traffic, I would have left earlier."},
 {lvl:2,cefr:"B2",q:"Students will perform better ___ they get enough sleep.",opts:["as long as","unless","even"],a:0,why:"'As long as' means 'on condition that', which fits the logic. 'Unless' means 'if not' and reverses the meaning, while 'even' alone cannot join two clauses.",natural:"Students perform better provided that they get enough sleep."},
 {lvl:3,cefr:"C1",q:"If the city had invested in flood defences years ago, it ___ such severe damage now.",opts:["would not suffer","would not have suffered","will not suffer"],a:0,why:"This is a mixed conditional: a past condition ('had invested years ago') with a present result ('now'), so 'would not suffer' is correct. 'Would not have suffered' refers to the past and clashes with 'now'.",natural:"Had the city invested in flood defences years ago, it would not be suffering such severe damage now."},
 {lvl:3,cefr:"C1",q:"___ the government to raise the retirement age, there would be widespread protests.",opts:["Were","If","Should"],a:0,why:"'Were + subject + to-infinitive' is a formal inverted conditional meaning 'If the government raised'. 'If the government to raise' has no finite verb, and 'Should' must be followed by a bare infinitive ('Should the government raise').",natural:"Were the government to raise the retirement age, there would be widespread protests."},
 {lvl:3,cefr:"C1",q:"___ for the support of my family, I would never have finished my degree.",opts:["Had it not been","If it was not","Unless it had been"],a:0,why:"'Had it not been for' is the inverted third conditional, matching 'would never have finished'. 'If it was not for' belongs to the second conditional (present), and 'unless' cannot be used in this fixed expression.",natural:"Had it not been for my family's support, I would never have finished my degree."}
],
"passive":[
 {lvl:1,cefr:"B1",q:"English ___ in many countries around the world.",opts:["is spoken","speaks","is speaking"],a:0,why:"The language does not perform the action; people speak it, so the passive 'is spoken' is needed. 'English speaks' wrongly makes the language the doer.",natural:"English is spoken in many countries around the world."},
 {lvl:1,cefr:"B1",q:"The Eiffel Tower ___ for the 1889 World's Fair.",opts:["built","was built","has built"],a:1,why:"The tower received the action and the time is past, so the past simple passive 'was built' is correct. 'Built' alone makes the tower the builder.",natural:"The Eiffel Tower was built for the 1889 World's Fair."},
 {lvl:2,cefr:"B2",q:"In the next stage, the mixture ___ to a temperature of 200°C.",opts:["heats","is heated","is heating"],a:1,why:"Process diagrams in Task 1 use the present simple passive, because the focus is on what happens to the material. 'Heats' and 'is heating' make the mixture do the heating.",natural:"In the next stage, the mixture is heated to 200°C."},
 {lvl:2,cefr:"B2",q:"Thousands of hectares of rainforest ___ every year.",opts:["are destroyed","destroy","are destroying"],a:0,why:"The rainforest is affected by the action, and 'every year' shows a regular fact, so the present simple passive 'are destroyed' is right. The active forms suggest the rainforest destroys something.",natural:"Thousands of hectares of rainforest are destroyed every year."},
 {lvl:2,cefr:"B2",q:"The survey ___ by over 2,000 university students last year.",opts:["completed","was completed","has been completed"],a:1,why:"'By over 2,000 students' shows the doers, so the survey is the receiver; 'last year' is finished time, so the past simple passive 'was completed' is required. 'Has been completed' cannot be used with 'last year'.",natural:"The survey was completed by over 2,000 university students last year."},
 {lvl:2,cefr:"B2",q:"A new vaccine ___ at the moment by researchers in Oxford.",opts:["is being tested","is tested","is testing"],a:0,why:"'At the moment' needs a continuous form, and the vaccine receives the action, so the present continuous passive 'is being tested' is correct. 'Is testing' makes the vaccine the tester.",natural:"Researchers in Oxford are currently testing a new vaccine."},
 {lvl:2,cefr:"B2",q:"More than 50 new species ___ in the region since 2015.",opts:["have been discovered","were discovered","have discovered"],a:0,why:"'Since 2015' needs the present perfect, and species are discovered by scientists, so the present perfect passive 'have been discovered' is required. 'Have discovered' is active and wrongly makes the species the discoverers.",natural:"More than 50 new species have been discovered in the region since 2015."},
 {lvl:3,cefr:"C1",q:"Renewable energy ___ to account for half of all electricity generation by 2040.",opts:["is expected","expects","is expecting"],a:0,why:"'Be expected to' is an impersonal passive used for forecasts, with no need to say who expects. 'Renewable energy expects' wrongly gives the subject a human ability.",natural:"Renewables are expected to account for half of all electricity generation by 2040."},
 {lvl:3,cefr:"C1",q:"The manuscript is ___ to have been written in the 14th century.",opts:["thought","thinking","think"],a:0,why:"The pattern 'subject + be + thought/believed + perfect infinitive' is a formal passive for past beliefs. 'Is thinking' is active and would mean the manuscript itself thinks.",natural:"The manuscript is thought to date from the 14th century."},
 {lvl:3,cefr:"C1",q:"Many workers complained about ___ to work overtime without extra pay.",opts:["being made","making","be made"],a:0,why:"After a preposition ('about') we need an -ing form, and the workers receive the action, so the passive gerund 'being made' is correct. 'Making' would mean the workers forced someone else, and 'be made' is not possible after a preposition.",natural:"Many workers complained about being forced to work overtime without extra pay."}
],
"relative":[
 {lvl:1,cefr:"B1",q:"The woman ___ lives next door is a doctor.",opts:["who","which","what"],a:0,why:"'Who' is the relative pronoun for people. 'Which' is for things, and 'what' cannot introduce a relative clause after a noun.",natural:"The woman who lives next door is a doctor."},
 {lvl:1,cefr:"B1",q:"This is the book ___ I told you about.",opts:["what","which","who"],a:1,why:"After a noun (the book), use 'which' or 'that'. 'What' means 'the thing that' and cannot follow a noun; it is a frequent error from Portuguese 'o que'.",natural:"This is the book I told you about."},
 {lvl:2,cefr:"B2",q:"Brazil, ___ population exceeds 200 million, is the largest country in South America.",opts:["which","whose","that"],a:1,why:"'Whose' shows possession (Brazil's population) and can be used for countries and things. 'Which population' is ungrammatical, and 'that' cannot be used in a non-defining clause with commas.",natural:"Brazil, whose population exceeds 200 million, is the largest country in South America."},
 {lvl:2,cefr:"B2",q:"2008 was the year ___ the global financial crisis began.",opts:["which","when","where"],a:1,why:"After a time noun (the year), 'when' introduces a clause that is complete in itself ('the crisis began'). 'Which' would need a missing object or subject, and 'where' is for places.",natural:"2008 was the year the global financial crisis began."},
 {lvl:2,cefr:"B2",q:"The government announced new taxes, ___ angered many small business owners.",opts:["that","which","what"],a:1,why:"To refer back to the whole previous clause, use ', which'. 'That' is not possible after a comma, and 'what' cannot refer back to a clause.",natural:"The government announced new taxes, which angered many small business owners."},
 {lvl:2,cefr:"B2",q:"The Amazon, ___ is often called the lungs of the planet, is under threat.",opts:["that","which","who"],a:1,why:"Non-defining clauses (between commas) about things use 'which', never 'that'. 'Who' is only for people.",natural:"The Amazon, often called the lungs of the planet, is under threat."},
 {lvl:2,cefr:"B2",q:"The reason ___ many young people leave rural areas is the lack of jobs.",opts:["why","because","which"],a:0,why:"'The reason why' is the standard relative structure. 'The reason because' is a common error: 'because' is a conjunction and cannot follow 'the reason' as a relative word.",natural:"The main reason many young people leave rural areas is the lack of jobs."},
 {lvl:3,cefr:"C1",q:"The researchers interviewed 50 farmers, most of ___ had experienced crop failure.",opts:["them","whom","who"],a:1,why:"After a quantifier + 'of' in a relative clause (most of, some of, all of), use 'whom' for people. 'Most of them' creates a comma splice, joining two sentences with only a comma, and 'who' cannot follow a preposition.",natural:"The researchers interviewed 50 farmers, most of whom had experienced crop failure."},
 {lvl:3,cefr:"C1",q:"The extent to ___ technology improves learning is still debated.",opts:["which","that","what"],a:0,why:"After a preposition, only 'which' (things) or 'whom' (people) can be used: 'the extent to which'. 'To that' and 'to what' are not possible in this relative structure.",natural:"The extent to which technology improves learning is still debated."},
 {lvl:3,cefr:"C1",q:"Anyone ___ to apply for the grant must submit a proposal by May.",opts:["wishing","who wishing","wishes"],a:0,why:"'Wishing' is a reduced relative clause meaning 'who wishes'. 'Who wishing' mixes the full and reduced forms, and 'wishes' alone creates two finite verbs in one clause.",natural:"Anyone wishing to apply for the grant must submit a proposal by May."}
],
"modals":[
 {lvl:1,cefr:"B1",q:"You ___ smoke inside the building; it's against the law.",opts:["mustn't","don't have to","needn't"],a:0,why:"'Mustn't' expresses prohibition, which fits 'against the law'. 'Don't have to' and 'needn't' mean there is no obligation, so smoking would be optional, which is the opposite meaning.",natural:"Smoking is prohibited inside the building."},
 {lvl:1,cefr:"B1",q:"___ you help me with this form, please?",opts:["Could","Must","Should"],a:0,why:"'Could you...?' is the polite way to make a request. 'Must you...?' sounds like a complaint, and 'Should you...?' asks for advice or a hypothetical, not a favour.",natural:"Could you help me with this form, please?"},
 {lvl:2,cefr:"B2",q:"She ___ be at home; I can see her car outside.",opts:["must","can","should"],a:0,why:"'Must' expresses a logical deduction based on evidence (the car). 'Can' is not used for deductions about a specific present situation, and 'should' expresses expectation or advice rather than certainty.",natural:"She must be at home; her car is outside."},
 {lvl:2,cefr:"B2",q:"He ___ have taken the train; it was cancelled because of the strike.",opts:["can't","mustn't","shouldn't"],a:0,why:"'Can't have + past participle' shows a negative deduction about the past: it is impossible. 'Mustn't have' is not used for deductions in standard British English, and 'shouldn't have' expresses criticism.",natural:"He can't have taken the train, as it was cancelled because of the strike."},
 {lvl:2,cefr:"B2",q:"Parents ___ to limit the time their children spend on screens.",opts:["should","ought","must"],a:1,why:"'Ought' is the only modal here followed by 'to'. 'Should to' and 'must to' are frequent errors; 'should' and 'must' take the bare infinitive.",natural:"Parents ought to limit their children's screen time."},
 {lvl:2,cefr:"B2",q:"In the future, robots ___ able to perform most household tasks.",opts:["can be","will be","could"],a:1,why:"'Can' has no future form, so we use 'will be able to'. 'Can be able to' repeats the idea of ability twice and is a common error; 'could able' has no verb 'be'.",natural:"In the future, robots will be able to perform most household tasks."},
 {lvl:2,cefr:"B2",q:"When I was ten, I ___ speak three languages.",opts:["could","can","must"],a:0,why:"'Could' expresses general ability in the past. 'Can' refers to the present and clashes with 'when I was ten'; 'must' expresses obligation, not ability.",natural:"By the age of ten, I could speak three languages."},
 {lvl:3,cefr:"C1",q:"You ___ have told me about the change in schedule; I waited for an hour!",opts:["should","must","would"],a:0,why:"'Should have + past participle' criticises a past action that did not happen. 'Must have told me' is a deduction (it is certain you told me), which contradicts the complaint.",natural:"You should have told me the schedule had changed; I waited for an hour!"},
 {lvl:3,cefr:"C1",q:"Governments ___ well need to introduce stricter regulations if emissions continue to rise.",opts:["may","must","should"],a:0,why:"'May well' is a fixed expression meaning 'it is quite likely that', ideal for cautious Task 2 predictions. 'Must well' and 'should well' are not used in English.",natural:"Governments may well need to introduce stricter regulations if emissions keep rising."},
 {lvl:3,cefr:"C1",q:"Students ___ submit their essays by Friday, but late submissions are accepted with a penalty.",opts:["are supposed to","mustn't","needn't to"],a:0,why:"'Be supposed to' expresses an expected rule that is not always followed, which matches 'but late submissions are accepted'. 'Mustn't' means prohibition, and 'needn't to' is ungrammatical because 'needn't' takes a bare infinitive.",natural:"Essays are supposed to be submitted by Friday, although late work is accepted with a penalty."}
],
"complex":[
 {lvl:1,cefr:"B1",q:"I stayed at home ___ I was feeling ill.",opts:["because","because of","so"],a:0,why:"'Because' is followed by a clause (subject + verb: I was feeling). 'Because of' must be followed by a noun phrase, and 'so' introduces a result, not a reason.",natural:"I stayed at home because I wasn't feeling well."},
 {lvl:1,cefr:"B1",q:"___ she was tired, she finished her homework.",opts:["Although","Despite","However"],a:0,why:"'Although' joins two clauses and shows contrast. 'Despite' must be followed by a noun or -ing form, and 'However' is an adverb that cannot join two clauses with only a comma.",natural:"Although she was tired, she finished her homework."},
 {lvl:2,cefr:"B2",q:"Which sentence is grammatically complete?",opts:["Because many people cannot afford housing.","Many people cannot afford housing because prices have doubled.","Prices doubling in the last decade."],a:1,why:"Option B has a main clause plus a subordinate clause, so it is complete. Option A is only a subordinate clause (a fragment), and option C has no finite verb.",natural:"Many people cannot afford housing because prices have doubled."},
 {lvl:2,cefr:"B2",q:"Many people move to cities ___ they can find better jobs.",opts:["so that","in order to","for"],a:0,why:"'So that' introduces a purpose clause with a subject and a modal (they can find). 'In order to' must be followed by a bare infinitive, and 'for' + clause is a Portuguese transfer from 'para que'.",natural:"Many people move to cities in order to find better jobs."},
 {lvl:2,cefr:"B2",q:"___ the cost of living is rising, many families are struggling.",opts:["Since","Despite","Due to"],a:0,why:"'Since' (meaning 'because') is followed by a full clause. 'Due to' needs a noun phrase ('due to the rising cost of living'), and 'despite' shows contrast, not cause.",natural:"With the cost of living rising, many families are struggling."},
 {lvl:2,cefr:"B2",q:"___ the government invests in public transport, congestion will continue to grow.",opts:["Unless","Despite","Even"],a:0,why:"'Unless' means 'if... not' and introduces a condition clause. 'Despite' cannot be followed by a clause, and 'even' alone is not a conjunction (we need 'even if').",natural:"Unless the government invests in public transport, congestion will continue to worsen."},
 {lvl:2,cefr:"B2",q:"Which sentence avoids a comma splice?",opts:["Tourism creates jobs, it also damages the environment.","Tourism creates jobs; however, it also damages the environment.","Tourism creates jobs, however it also damages the environment."],a:1,why:"Two independent clauses can be joined with a semicolon and 'however'. Joining them with only a comma, with or without 'however', is a comma splice, a frequent error in Task 2.",natural:"Although tourism creates jobs, it also damages the environment."},
 {lvl:3,cefr:"C1",q:"___ funding for the arts is limited, many museums depend on private donations.",opts:["Given that","In spite of","Owing to"],a:0,why:"'Given that' is a conjunction meaning 'considering the fact that' and is followed by a clause. 'Owing to' and 'in spite of' are prepositions and need a noun phrase, and 'in spite of' also expresses the wrong logic.",natural:"Given that arts funding is limited, many museums rely on private donations."},
 {lvl:3,cefr:"C1",q:"Not only ___ congestion, but it also improves air quality.",opts:["does cycling reduce","cycling reduces","cycling does reduce"],a:0,why:"When 'Not only' starts a sentence, the subject and auxiliary are inverted, as in a question: 'Not only does cycling reduce'. The normal word order is a common error.",natural:"Not only does cycling reduce congestion, but it also improves air quality."},
 {lvl:3,cefr:"C1",q:"___ by the results, the researchers decided to extend the study.",opts:["Encouraged","Encouraging","Having encouraged"],a:0,why:"The researchers were encouraged by the results, so a past participle clause with a passive meaning is needed. 'Encouraging' and 'Having encouraged' are active and would mean the researchers encouraged someone else.",natural:"Encouraged by the results, the researchers decided to extend the study."}
],
"linking":[
 {lvl:1,cefr:"B1",q:"I wanted to go to the concert, ___ the tickets were sold out.",opts:["but","so","because"],a:0,why:"'But' introduces a contrast between the wish and the problem. 'So' would introduce a result and 'because' a reason, neither of which fits the logic.",natural:"I wanted to go to the concert, but it was sold out."},
 {lvl:1,cefr:"B1",q:"First, the fruit is washed. ___, it is cut into small pieces.",opts:["Then","In conclusion","At last"],a:0,why:"'Then' introduces the next step of a process. 'At last' means 'after a long wait' and is a transfer from Portuguese 'por último'; 'In conclusion' is for ending an essay.",natural:"First, the fruit is washed, and then it is cut into small pieces."},
 {lvl:2,cefr:"B2",q:"Online learning is flexible. ___, it can be isolating for some students.",opts:["On the other hand","Moreover","Therefore"],a:0,why:"The second sentence presents a disadvantage that contrasts with the first, so 'On the other hand' fits. 'Moreover' adds a similar point and 'Therefore' introduces a result.",natural:"Although online learning is flexible, it can be isolating for some students."},
 {lvl:2,cefr:"B2",q:"Many cities suffer from air pollution. ___, Delhi regularly exceeds safe limits.",opts:["For example","In contrast","As a result"],a:0,why:"Delhi is a specific case of the general statement, so 'For example' is correct. 'In contrast' would suggest Delhi is different, and 'As a result' implies cause and effect.",natural:"Many cities suffer from air pollution; Delhi, for example, regularly exceeds safe limits."},
 {lvl:2,cefr:"B2",q:"Fuel prices rose sharply. ___, more people started using public transport.",opts:["Consequently","Nevertheless","Furthermore"],a:0,why:"The second sentence is a result of the first, so 'Consequently' is right. 'Nevertheless' signals an unexpected contrast, and 'Furthermore' simply adds information.",natural:"As fuel prices rose sharply, more people switched to public transport."},
 {lvl:2,cefr:"B2",q:"___ my point of view, public transport should be free.",opts:["In","From","On"],a:1,why:"The fixed phrase is 'from my point of view' (or 'in my view' / 'in my opinion'). 'In my point of view' mixes two expressions and is a very common error.",natural:"In my view, public transport should be free."},
 {lvl:2,cefr:"B2",q:"Sales in Europe declined, ___ sales in Asia grew by 15%.",opts:["whereas","despite","moreover"],a:0,why:"'Whereas' is a conjunction that joins two clauses and compares contrasting data, ideal for Task 1. 'Despite' cannot be followed by a clause, and 'moreover' adds rather than contrasts.",natural:"Sales in Europe declined, whereas sales in Asia grew by 15%."},
 {lvl:3,cefr:"C1",q:"Renewable energy is cleaner; ___, its initial costs remain high.",opts:["nonetheless","otherwise","namely"],a:0,why:"'Nonetheless' introduces a contrasting fact despite what was just said. 'Otherwise' means 'if not', and 'namely' introduces a specific explanation or list.",natural:"Renewable energy is cleaner; nonetheless, its initial costs remain high."},
 {lvl:3,cefr:"C1",q:"Some argue that homework is essential. ___ this may be true for older students, younger children benefit more from play.",opts:["While","Despite","However"],a:0,why:"'While' is a conjunction used to concede a point before contrasting it, and it joins the two clauses. 'However' cannot introduce a subordinate clause in this way, and 'despite' needs a noun phrase.",natural:"While this may be true for older students, younger children benefit more from play."},
 {lvl:3,cefr:"C1",q:"Several factors contribute to obesity, ___ poor diet and lack of exercise.",opts:["namely","such","in other words"],a:0,why:"'Namely' introduces the exact items being referred to. 'Such' alone is incomplete (it should be 'such as'), and 'in other words' introduces a rephrasing, not a list.",natural:"Several factors contribute to obesity, namely poor diet and lack of exercise."}
],
"sva":[
 {lvl:1,cefr:"A2",q:"My brother ___ in a bank in São Paulo.",opts:["work","works","working"],a:1,why:"Third person singular subjects (my brother) take -s in the present simple: 'works'. Dropping the -s is one of the most frequent errors at all levels.",natural:"My brother works for a bank in São Paulo."},
 {lvl:1,cefr:"B1",q:"Everybody in my family ___ football.",opts:["love","loves","are loving"],a:1,why:"'Everybody', 'everyone' and 'nobody' are grammatically singular, so the verb takes -s: 'loves'. Using a plural verb is a common error because the meaning feels plural.",natural:"Everyone in my family loves football."},
 {lvl:2,cefr:"B2",q:"The police ___ investigating the cause of the fire.",opts:["is","are","has"],a:1,why:"'Police' is always treated as plural in English, so it takes 'are'. In Portuguese 'a polícia' is singular, which leads to 'the police is'.",natural:"The police are investigating the cause of the fire."},
 {lvl:2,cefr:"B2",q:"Mathematics ___ a compulsory subject in most schools.",opts:["are","is","were"],a:1,why:"Academic subjects ending in -s (mathematics, economics, physics) are singular and take 'is'. The final -s does not make them plural.",natural:"Mathematics is a compulsory subject in most schools."},
 {lvl:2,cefr:"B2",q:"A number of countries ___ introduced a sugar tax.",opts:["has","have","is"],a:1,why:"'A number of' means 'several' and takes a plural verb: 'have'. Only 'the number of' (the total) takes a singular verb.",natural:"A number of countries have introduced a sugar tax."},
 {lvl:2,cefr:"B2",q:"The information in these reports ___ out of date.",opts:["are","is","were"],a:1,why:"'Information' is uncountable and takes a singular verb, even when followed by a plural noun ('reports'). The verb agrees with the head noun, not with the nearest noun.",natural:"The information in these reports is out of date."},
 {lvl:2,cefr:"B2",q:"There ___ a lot of people waiting outside the museum.",opts:["was","were","is"],a:1,why:"With 'there is/are', the verb agrees with the noun that follows: 'people' is plural, so 'were'. 'There was a lot of people' (influenced by 'tinha muita gente') is a common error.",natural:"There were a lot of people waiting outside the museum."},
 {lvl:3,cefr:"C1",q:"Neither the teacher nor the students ___ aware of the change.",opts:["was","were","is"],a:1,why:"With 'neither... nor', the verb agrees with the nearer subject. 'The students' is plural, so 'were' is correct; 'was' would agree with 'the teacher', which is further away.",natural:"Neither the teacher nor the students were aware of the change."},
 {lvl:3,cefr:"C1",q:"The percentage of households with internet access ___ from 40% to 85%.",opts:["have risen","has risen","are rising"],a:1,why:"The head of the subject is 'the percentage' (singular), not 'households', so the verb is 'has risen'. Learners often make the verb agree with the closest plural noun.",natural:"The percentage of households with internet access has risen from 40% to 85%."},
 {lvl:3,cefr:"C1",q:"What surprised the researchers most ___ the speed at which the disease spread.",opts:["was","were","are"],a:0,why:"A 'what'-clause used as a subject is singular, and here it is also completed by a singular noun ('the speed'), so 'was' is correct. 'Were' wrongly agrees with 'the researchers' inside the clause.",natural:"What surprised the researchers most was how quickly the disease spread."}
],
"gerunds":[
 {lvl:1,cefr:"B1",q:"I don't mind ___ early in the morning.",opts:["to work","working","work"],a:1,why:"'Mind' is always followed by the -ing form: 'I don't mind working'. 'Mind to work' is a common error by analogy with verbs like 'want to'.",natural:"I don't mind working early in the morning."},
 {lvl:1,cefr:"B1",q:"She is thinking about ___ a new language.",opts:["learn","to learn","learning"],a:2,why:"After a preposition (about), English uses the -ing form. Portuguese uses the infinitive after prepositions ('pensando em aprender'), which leads to 'about to learn' or 'about learn'.",natural:"She is thinking about learning a new language."},
 {lvl:2,cefr:"B2",q:"___ a second language can improve your job prospects.",opts:["Learn","Learning","To learning"],a:1,why:"A gerund ('Learning') can act as the subject of a sentence. The bare form 'Learn' cannot be a subject, and 'To learning' mixes an infinitive marker with an -ing form.",natural:"Learning a second language can improve your career prospects."},
 {lvl:2,cefr:"B2",q:"Many people avoid ___ public transport late at night.",opts:["to use","using","use"],a:1,why:"'Avoid' is followed by the -ing form, never by the infinitive. 'Avoid to use' is a frequent transfer from Portuguese 'evitar usar'.",natural:"Many people avoid using public transport late at night."},
 {lvl:2,cefr:"B2",q:"I'm considering ___ a master's degree in museum studies.",opts:["doing","to do","do"],a:0,why:"'Consider' takes the -ing form when it means 'think about doing something'. 'Considering to do' is a common error.",natural:"I'm considering doing a master's in museum studies."},
 {lvl:2,cefr:"B2",q:"It's no use ___ about the weather; we can't change it.",opts:["to complain","complaining","complain"],a:1,why:"The fixed expression 'It's no use' is followed by the -ing form. 'It's no use to complain' is non-standard.",natural:"There's no point complaining about the weather; we can't change it."},
 {lvl:2,cefr:"B2",q:"Instead of ___ new roads, the city should improve public transport.",opts:["build","to build","building"],a:2,why:"'Instead of' ends with a preposition, so it must be followed by a gerund. 'Instead of to build' copies Portuguese 'em vez de construir'.",natural:"Rather than building new roads, the city should improve public transport."},
 {lvl:3,cefr:"C1",q:"The minister denied ___ about the budget cuts in advance.",opts:["having been informed","to have been informed","to be informed"],a:0,why:"'Deny' takes the -ing form; here a perfect passive gerund ('having been informed') shows an earlier action done to the minister. Infinitive forms are not possible after 'deny'.",natural:"The minister denied having been told about the budget cuts in advance."},
 {lvl:3,cefr:"C1",q:"There is little point in ___ stricter laws if they are not enforced.",opts:["introducing","to introduce","introduce"],a:0,why:"'There is little point in' ends with the preposition 'in', which requires a gerund. 'In to introduce' is impossible, as prepositions are never followed by 'to + verb' in this pattern.",natural:"There is little point in introducing stricter laws if they are not enforced."},
 {lvl:3,cefr:"C1",q:"Many residents object to ___ for services they do not use.",opts:["being charged","be charged","charging"],a:0,why:"In 'object to', 'to' is a preposition, so it is followed by an -ing form; the residents receive the action, so the passive gerund 'being charged' is needed. 'Object to be charged' treats 'to' as an infinitive marker, and 'charging' would mean the residents charge others.",natural:"Many residents object to paying for services they do not use."}
],
"infinitives":[
 {lvl:1,cefr:"B1",q:"I want ___ abroad next year.",opts:["study","to study","studying"],a:1,why:"'Want' is followed by 'to + infinitive'. 'I want study' omits 'to', and 'want studying' is not used in this meaning.",natural:"I want to study abroad next year."},
 {lvl:1,cefr:"B1",q:"We went to the library ___ some books.",opts:["for borrow","to borrow","for borrowing"],a:1,why:"Purpose after a verb is expressed with 'to + infinitive'. 'For borrow' and 'for borrowing' are transfers from Portuguese 'para pegar'.",natural:"We went to the library to borrow some books."},
 {lvl:2,cefr:"B2",q:"The government has promised ___ more teachers.",opts:["hiring","to hire","hire"],a:1,why:"'Promise' is followed by 'to + infinitive'. 'Promised hiring' uses the wrong verb pattern.",natural:"The government has pledged to recruit more teachers."},
 {lvl:2,cefr:"B2",q:"My parents made me ___ the piano when I was young.",opts:["to practise","practise","practising"],a:1,why:"'Make + object' is followed by the bare infinitive (without 'to'). 'Made me to practise' is a very common error; 'to' only appears in the passive ('I was made to practise').",natural:"My parents made me practise the piano when I was young."},
 {lvl:2,cefr:"B2",q:"It is difficult for young people ___ affordable housing.",opts:["finding","to find","find"],a:1,why:"The structure 'It is + adjective + for + person + to-infinitive' is fixed. 'For young people finding' does not complete the pattern.",natural:"Young people find it difficult to secure affordable housing."},
 {lvl:2,cefr:"B2",q:"Many people seem ___ that the problem will solve itself.",opts:["believing","to believe","believe"],a:1,why:"'Seem' is followed by 'to + infinitive'. 'Seem believing' and 'seem believe' are not possible patterns.",natural:"Many people seem to believe the problem will solve itself."},
 {lvl:2,cefr:"B2",q:"Remember ___ your passport before you leave for the airport.",opts:["to take","taking","take"],a:0,why:"'Remember to do' refers to a future action you must not forget. 'Remember taking' means recalling something that already happened, which does not fit an instruction.",natural:"Don't forget to take your passport before you leave for the airport."},
 {lvl:3,cefr:"C1",q:"The company is reported ___ record profits last year.",opts:["to have made","to make","making"],a:0,why:"After 'is reported/said/thought', a past action takes the perfect infinitive 'to have made'. 'To make' would refer to the present or future and clashes with 'last year'.",natural:"The company is reported to have made record profits last year."},
 {lvl:3,cefr:"C1",q:"The new policy is designed ___ the gap between rich and poor.",opts:["to narrow","narrowing","for narrowing"],a:0,why:"'Be designed to + infinitive' expresses the purpose of a plan. 'For narrowing' is a Portuguese-style purpose structure ('para reduzir') and sounds unnatural here.",natural:"The new policy aims to narrow the gap between rich and poor."},
 {lvl:3,cefr:"C1",q:"Governments need to encourage people ___ their energy consumption.",opts:["reduce","to reduce","reducing"],a:1,why:"'Encourage + object + to-infinitive' is the correct pattern. Leaving out 'to' or using the -ing form after the object is incorrect.",natural:"Governments need to encourage people to cut their energy consumption."}
],
"comparatives":[
 {lvl:1,cefr:"B1",q:"My new job is ___ than my old one.",opts:["more interesting","interestinger","more interestinger"],a:0,why:"Long adjectives (three or more syllables) form the comparative with 'more'. Adding -er, or using both 'more' and -er, is incorrect.",natural:"My new job is more interesting than my old one."},
 {lvl:1,cefr:"B1",q:"Rio de Janeiro is ___ than São Paulo in summer.",opts:["hoter","hotter","more hot"],a:1,why:"Short adjectives ending in consonant-vowel-consonant double the final consonant: hot becomes hotter. 'More hot' is incorrect for one-syllable adjectives.",natural:"Rio de Janeiro is hotter than São Paulo in summer."},
 {lvl:2,cefr:"B2",q:"The number of cars in 2020 was twice ___ in 1990.",opts:["as high as","higher than","as higher as"],a:0,why:"Multiples are expressed with 'twice/three times + as + adjective + as'. 'Twice higher than' is a common error, and 'as higher as' wrongly mixes the comparative with 'as... as'.",natural:"The number of cars in 2020 was twice as high as in 1990."},
 {lvl:2,cefr:"B2",q:"Coal is ___ polluting source of energy.",opts:["the most","most","the more"],a:0,why:"Superlatives need 'the' + 'most' (for long adjectives). 'Most' without 'the' is a common omission, and 'the more' is a comparative, used for two things.",natural:"Coal is the most polluting source of energy."},
 {lvl:2,cefr:"B2",q:"Spending on education was slightly ___ than spending on defence.",opts:["lower","less low","lowest"],a:0,why:"'Low' is a short adjective, so its comparative is 'lower' and can be modified by 'slightly'. 'Less low' is unnatural, and 'lowest' is a superlative that cannot be followed by 'than'.",natural:"Spending on education was slightly lower than spending on defence."},
 {lvl:2,cefr:"B2",q:"Living in the countryside is not ___ stressful ___ living in a big city.",opts:["as / as","so / than","more / as"],a:0,why:"Equality comparisons use 'as + adjective + as'. 'So... than' and 'more... as' combine two different structures.",natural:"Living in the countryside is less stressful than living in a big city."},
 {lvl:2,cefr:"B2",q:"Women's life expectancy is higher than ___ men.",opts:["that of","of","those of"],a:0,why:"To avoid repeating a singular noun ('life expectancy'), use 'that of'. 'Higher than men' compares life expectancy with people, and 'those of' is for plural nouns.",natural:"Women's life expectancy is higher than that of men."},
 {lvl:3,cefr:"C1",q:"The older people get, ___ they tend to sleep.",opts:["the less","less","the fewer"],a:0,why:"The double comparative needs 'the' in both parts: 'the older..., the less...'. Omitting 'the' is a common error, and 'fewer' is for countable nouns, not for a verb like sleep.",natural:"The older people get, the less they tend to sleep."},
 {lvl:3,cefr:"C1",q:"Sales in March were by far ___ of the year.",opts:["the highest","higher","the most high"],a:0,why:"'By far' intensifies a superlative, and 'of the year' signals a superlative comparison: 'the highest'. 'The most high' is incorrect for a short adjective.",natural:"March saw by far the highest sales of the year."},
 {lvl:3,cefr:"C1",q:"There were considerably ___ accidents in 2022 than in 2012.",opts:["fewer","less","lesser"],a:0,why:"'Accidents' is a plural countable noun, so it takes 'fewer'. 'Less' is for uncountable nouns (less traffic), and 'lesser' means 'smaller in importance'.",natural:"There were considerably fewer accidents in 2022 than in 2012."}
],
"reported":[
 {lvl:1,cefr:"B1",q:"She told me she ___ tired after the long journey.",opts:["has","was","were"],a:1,why:"After a past reporting verb ('told'), the present 'am' usually shifts back to 'was'. 'Were' does not agree with 'she', and 'has' is the wrong verb (in English you are tired, not have tiredness).",natural:"She told me she was tired after the long journey."},
 {lvl:1,cefr:"B1",q:"He ___ me that the exam had been cancelled.",opts:["said","told","spoke"],a:1,why:"'Tell' is followed directly by the person (told me). 'Said me' is wrong because 'say' needs 'to' before a person (said to me) and is usually used without one.",natural:"He told me the exam had been cancelled."},
 {lvl:2,cefr:"B2",q:"The manager asked us ___ late again.",opts:["not to be","to not being","don't be"],a:0,why:"Reported negative requests and orders use 'ask/tell + object + not to + infinitive'. 'Don't be' is direct speech, and 'to not being' mixes two forms.",natural:"The manager asked us not to be late again."},
 {lvl:2,cefr:"B2",q:"She asked me if I ___ to the conference the following week.",opts:["was going","am going","will go"],a:0,why:"In reported questions after a past verb, 'am going' shifts back to 'was going', which also matches 'the following week'. 'Am going' and 'will go' ignore the backshift.",natural:"She asked me whether I was going to the conference the following week."},
 {lvl:2,cefr:"B2",q:"The tourist wanted to know what time ___.",opts:["the museum opened","did the museum open","does the museum open"],a:0,why:"Reported questions use normal statement word order (subject + verb) and no auxiliary 'do'. Keeping question order is a very common error in Speaking.",natural:"The tourist wanted to know what time the museum opened."},
 {lvl:2,cefr:"B2",q:"He said he ___ the report the day before.",opts:["had finished","has finished","finishes"],a:0,why:"An action before the moment of speaking, reported with 'said' and 'the day before', takes the past perfect 'had finished'. 'Has finished' does not backshift and clashes with 'the day before'.",natural:"He said he had finished the report the day before."},
 {lvl:2,cefr:"B2",q:"My teacher recommended ___ more English podcasts.",opts:["listening to","to listen","me to listening"],a:0,why:"'Recommend' is followed by an -ing form (or a that-clause), not 'to + infinitive'. 'Recommended to listen' is a frequent error.",natural:"My teacher recommended listening to more English podcasts."},
 {lvl:3,cefr:"C1",q:"The report claimed that the scheme ___ unemployment by 5% the previous year.",opts:["had reduced","has reduced","reduces"],a:0,why:"'The previous year' refers to a time before the report was made, so the past perfect 'had reduced' is needed. 'Has reduced' would connect the result to now and cannot be used with a finished past time.",natural:"The report claimed that the scheme had cut unemployment by 5% the previous year."},
 {lvl:3,cefr:"C1",q:"The researchers concluded that more data ___ before any firm recommendations could be made.",opts:["would be needed","will be needed","is needed"],a:0,why:"In reported speech after a past verb ('concluded'), 'will' shifts to 'would', which also agrees with 'could be made'. 'Will be needed' breaks the sequence of tenses.",natural:"The researchers concluded that more data would be needed before firm recommendations could be made."},
 {lvl:3,cefr:"C1",q:"She apologised ___ the meeting.",opts:["for missing","to miss","that she missed"],a:0,why:"'Apologise for + -ing' is the standard reporting pattern. 'Apologised to miss' is wrong, and 'apologised that she missed' is unnatural in standard English.",natural:"She apologised for missing the meeting."}
],
};
export const NEW_TOPICS = [];
